#!/usr/bin/env python3
"""Binding texts for the hosted runs of a Math- PR head from runs447_<head>.json (collected read-only by bind_runs447_v2.py with
R7_HEAD) and the locally verified merge identity. Env: R7_PR (445|447), R7_HEAD, R7_MERGE, R7_TREE, R7_BASE, R7_BASE_DESC,
R7_HEADLINE (what this head is). Refuses unless every run is completed. C422-E1: every run mention names the PR head AND the
actual tested merge commit. Artifacts: GitHub's digest only, bytes not downloaded here."""
import json, os
from pathlib import Path
S = Path('<SCRATCH>')
PR, HEAD, MERGE, TREE, BASE = os.environ['R7_PR'], os.environ['R7_HEAD'], os.environ['R7_MERGE'], os.environ['R7_TREE'], os.environ['R7_BASE']
BASE_DESC, HEADLINE = os.environ['R7_BASE_DESC'], os.environ['R7_HEADLINE']
runs = json.loads((S / f'lvs/r7/runs447_{HEAD[:8]}.json').read_text())
assert all(r['status'] == 'completed' for r in runs), [(r['run'], r['status']) for r in runs]
assert all(r['head_sha'] == HEAD and r['event'] == 'pull_request' and r['attempt'] == 1 for r in runs) and len(runs) == 3
by = {r['name'].split(' (')[0]: r for r in runs}
stmt = by['Lean statement specifications']; prf = by['Lean statement proofs']; rep = by['Downstream hard-gate exact replay']
def arts(r): return '; '.join(f"artifact `{a['name']}` (id {a['id']}, {a['size']} B, GitHub digest `{a['digest']}`)" for a in r['artifacts']) or 'no artifact'
def jobs(r): return ', '.join(f"{j['name']} {j['conclusion']}" for j in r['jobs'])
merge_clause = (f'actual tested merge `{MERGE}` (= `refs/pull/{PR}/merge` at run time, parents `{BASE[:8]}` ({BASE_DESC}) and `{HEAD[:8]}`, tree `{TREE[:8]}` = the head\'s tree, '
                'verified locally from the fetched ref: the tested merge has exactly the head\'s tree)')
line = (f"the three pull_request runs on PR head `{HEAD[:8]}`, {merge_clause}, all attempt 1: "
        f"`lean-specifications.yml` run {stmt['run']} **{stmt['conclusion']}** (job {jobs(stmt)}; {arts(stmt)}); "
        f"`lean-specification-proofs.yml` run {prf['run']} **{prf['conclusion']}** (job {jobs(prf)}; {arts(prf)}); "
        f"downstream hard-gate exact replay run {rep['run']} **{rep['conclusion']}** (jobs {jobs(rep)}; {arts(rep)}). "
        "Artifact bytes were not downloaded here (the API redirects to blob storage, which this session's client refuses); the digests are GitHub's. "
        "A green run is a record of a computation about the formal objects: not a review, not an alignment, not an acceptance; it moves no label.")
(S / f'lvs/r7/hosted_runs_line_{HEAD[:8]}.md').write_text(line + '\n')
ok = all(r['conclusion'] == 'success' for r in runs)
comment = (f"**Math-#{PR} hosted runs bound on head `{HEAD[:8]}` ({HEADLINE}): {'all three green' if ok else 'NOT all green, see below'}.** "
           "Anthropic Claude, session `session_01Cz7WZybv8znP64SpPj6sWY`. Organizational-independence credit 0. Scientific effect NONE.\n\n"
           f"- **Runs:** {line}\n"
           "- **What that means and does not:** execution and well-formedness evidence for the formal objects at this head; every registered declaration stays `specified`, nothing is proved, no inhabitant has been constructed (existence is neither proved nor refuted), no claim-level label moves, alignment PENDING_INDEPENDENT_REVIEW. The PR body carries the same binding.\n\n"
           "---\n_Generated by [Claude Code](https://claude.ai/code)_\n")
(S / f'lvs/r7/bind_comment_{PR}_{HEAD[:8]}.md').write_text(comment)
json.dump({'body': comment}, open(S / f'lvs/r7/bind_comment_{PR}_{HEAD[:8]}_payload.json', 'w'))
print('ALL GREEN' if ok else 'NOT GREEN', PR, HEAD[:8])
